ALTER TABLE public.erp_documents ADD CONSTRAINT erp_doc_totals_valid CHECK(subtotal>=0 AND tax_amount>=0 AND total=subtotal+tax_amount);
ALTER TABLE public.erp_document_items ADD CONSTRAINT erp_item_totals_valid CHECK(net_amount>=0 AND tax_amount>=0);
ALTER TABLE public.erp_journals ADD CONSTRAINT erp_journal_source_required CHECK((source_document_id IS NOT NULL)::integer + (source_payment_id IS NOT NULL)::integer = 1);
CREATE FUNCTION public.erp_header_balanced() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE n integer; d numeric; c numeric; BEGIN SELECT count(*),coalesce(sum(debit),0),coalesce(sum(credit),0) INTO n,d,c FROM public.erp_journal_lines WHERE journal_id=NEW.id; IF n<2 OR d<>c THEN RAISE EXCEPTION 'Every journal requires at least two balanced lines'; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER erp_header_balance_check AFTER INSERT ON public.erp_journals DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.erp_header_balanced();
CREATE FUNCTION public.erp_payment_limit() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE d public.erp_documents; paid numeric; BEGIN SELECT * INTO d FROM public.erp_documents WHERE id=NEW.document_id FOR UPDATE; SELECT coalesce(sum(amount),0) INTO paid FROM public.erp_payments WHERE document_id=d.id; IF d.status<>'posted' OR d.kind NOT IN ('invoice','bill') OR paid>d.total THEN RAISE EXCEPTION 'Payment requires a posted invoice or bill and cannot exceed its balance'; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER erp_payment_balance_check AFTER INSERT ON public.erp_payments DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.erp_payment_limit();
REVOKE INSERT,UPDATE,DELETE,TRUNCATE ON public.erp_documents,public.erp_document_items,public.erp_journals,public.erp_journal_lines,public.erp_payments,public.erp_audit_events FROM service_role;
REVOKE EXECUTE ON FUNCTION public.erp_check_balanced(),public.erp_immutable(),public.erp_document_lock(),public.erp_party_audit(),public.erp_party_validate(),public.erp_header_balanced(),public.erp_payment_limit() FROM PUBLIC,anon,authenticated;